import { test, expect } from '@playwright/test';

test.describe('Sticky Footer Navigation on Mobile', () => {
  test.beforeEach(async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });
    // Navigate to the application
    await page.goto('/');
  });

  test('should display sticky footer navigation on mobile viewport', async ({ page }) => {
    // Get the footer navigation element
    const footerNav = page.getByRole('navigation', { name: /footer/i });

    // Verify footer navigation is visible
    await expect(footerNav).toBeVisible();

    // Get the bounding box of the footer
    const footerBox = await footerNav.boundingBox();

    // Verify footer is at the bottom of the viewport
    expect(footerBox?.y).toBeDefined();
    expect(footerBox?.height).toBeDefined();
  });

  test('should keep footer navigation sticky when scrolling content', async ({ page }) => {
    // Get the main content area
    const mainContent = page.getByRole('main');

    // Get the footer navigation
    const footerNav = page.getByRole('navigation', { name: /footer/i });

    // Get initial footer position
    const initialFooterBox = await footerNav.boundingBox();
    const initialFooterY = initialFooterBox?.y;

    // Scroll down the page
    await mainContent.evaluate(el => {
      el.scrollTop = 500;
    });

    // Get footer position after scroll
    const scrolledFooterBox = await footerNav.boundingBox();
    const scrolledFooterY = scrolledFooterBox?.y;

    // Footer should remain in the same position (sticky behavior)
    expect(scrolledFooterY).toBe(initialFooterY);
  });

  test('should have accessible navigation items in sticky footer', async ({ page }) => {
    // Get all navigation links in footer
    const footerNav = page.getByRole('navigation', { name: /footer/i });
    const navLinks = footerNav.getByRole('link');

    // Verify at least one navigation link exists
    const linkCount = await navLinks.count();
    expect(linkCount).toBeGreaterThan(0);

    // Verify each link is visible and accessible
    for (let i = 0; i < linkCount; i++) {
      const link = navLinks.nth(i);
      await expect(link).toBeVisible();
      await expect(link).toHaveAttribute('href');
    }
  });

  test('should not overlap content with sticky footer on mobile', async ({ page }) => {
    // Get the main content
    const mainContent = page.getByRole('main');
    const footerNav = page.getByRole('navigation', { name: /footer/i });

    // Get bounding boxes
    const contentBox = await mainContent.boundingBox();
    const footerBox = await footerNav.boundingBox();

    // Verify footer doesn't overlap with main content
    if (contentBox && footerBox) {
      const contentBottom = contentBox.y + contentBox.height;
      const footerTop = footerBox.y;

      // Footer should start at or after content ends
      expect(footerTop).toBeGreaterThanOrEqual(contentBottom);
    }
  });

  test('should maintain footer visibility on small mobile screens', async ({ page }) => {
    // Set very small mobile viewport
    await page.setViewportSize({ width: 320, height: 568 });

    // Get footer navigation
    const footerNav = page.getByRole('navigation', { name: /footer/i });

    // Verify footer is still visible
    await expect(footerNav).toBeVisible();

    // Get footer dimensions
    const footerBox = await footerNav.boundingBox();

    // Verify footer width matches viewport
    expect(footerBox?.width).toBeLessThanOrEqual(320);
  });

  test('should have proper touch targets for footer navigation items', async ({ page }) => {
    // Get footer navigation links
    const footerNav = page.getByRole('navigation', { name: /footer/i });
    const navLinks = footerNav.getByRole('link');

    // Verify each link has adequate touch target size (minimum 44x44px)
    const linkCount = await navLinks.count();
    for (let i = 0; i < linkCount; i++) {
      const link = navLinks.nth(i);
      const box = await link.boundingBox();

      if (box) {
        // Check minimum touch target size
        expect(box.height).toBeGreaterThanOrEqual(44);
        expect(box.width).toBeGreaterThanOrEqual(44);
      }
    }
  });

  test('should display footer navigation icons or labels clearly', async ({ page }) => {
    // Get footer navigation
    const footerNav = page.getByRole('navigation', { name: /footer/i });

    // Get all buttons or links in footer
    const footerItems = footerNav.getByRole(/button|link/);

    // Verify footer items are visible
    const itemCount = await footerItems.count();
    expect(itemCount).toBeGreaterThan(0);

    // Verify each item has accessible text or aria-label
    for (let i = 0; i < itemCount; i++) {
      const item = footerItems.nth(i);
      const text = await item.textContent();
      const ariaLabel = await item.getAttribute('aria-label');

      // Item should have either visible text or aria-label
      expect(text?.trim() || ariaLabel).toBeTruthy();
    }
  });
});
